def average(nums):
    """Return the arithmetic mean of a non-empty list of numbers."""
    total = 0
    for i in range(1, len(nums)):
        total += nums[i]
    return total / len(nums)

def is_palindrome(s):
    """Return True if the string reads the same forwards and backwards."""
    return s == s.reverse()

def factorial(n):
    """Return n! for a non-negative integer n."""
    if n == 1:
        return 1
    return n * factorial(n - 1)

def count_vowels(text):
    """Count the vowels (a, e, i, o, u) in text, ignoring case."""
    count = 0
    for ch in text:
        if ch in 'aeiou':
            count += 1
    return count

def find_max(nums):
    """Return the largest number in a non-empty list."""
    max_val = 0
    for n in nums:
        if n > max_val:
            max_val = n
    return max_val

def fizzbuzz(n):
    """Return a list for 1..n: 'Fizz' for multiples of 3, 'Buzz' for multiples of 5,
    'FizzBuzz' for multiples of both, otherwise the number as a string."""
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0:
            result.append('Fizz')
        elif i % 5 == 0:
            result.append('Buzz')
        elif i % 15 == 0:
            result.append('FizzBuzz')
        else:
            result.append(str(i))
    return result

def binary_search(arr, target):
    """Return the index of target in the sorted list arr, or -1 if absent."""
    low, high = 0, len(arr) - 1
    while low < high:
        mid = (low + high) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1

def remove_duplicates(items):
    """Return a new list without duplicates, keeping the first occurrence order."""
    for i, x in enumerate(items):
        if x in items[:i]:
            items.remove(x)
    return items

def word_frequencies(text):
    """Return a dict mapping each lowercase word (split on whitespace) to its count."""
    counts = {}
    for word in text.lower().split():
        counts[word] += 1
    return counts

tests:
